INSERT INTO `about` (`id`, `title`, `content`, `image`) VALUES
(10, 'Professional & Trust-Oriented ', '<p data-start=\"327\" data-end=\"1243\"><strong data-start=\"327\" data-end=\"355\">About Amaken Real Estate</strong><br data-start=\"355\" data-end=\"358\" />At <strong data-start=\"361\" data-end=\"383\">Amaken Real Estate</strong>, we are more than just property consultants&mdash;we are your trusted partners in navigating the ever-evolving real estate landscape in the UAE. With a foundation built on integrity, transparency, and excellence, we provide a full suite of property services, including residential and commercial sales, rentals, property management, and investment advisory. Our team comprises experienced professionals who bring deep market knowledge, strategic insight, and a personalized approach to every transaction. Whether you\'re a first-time homebuyer, a seasoned investor, or a property owner seeking value-driven management, Amaken Real Estate is committed to delivering results with honesty and reliability. We take pride in offering tailor-made solutions that empower our clients to make informed, confident decisions in one of the world&rsquo;s most dynamic property markets.</p>', '60c1fc60797a902cf72fa68d_ATRR-11.jpeg'),
(11, NULL, '<p>\"At Amaken Real Estate, we believe that a property is more than just land and buildings &mdash; it\'s the cornerstone of dreams, stability, and growth. Whether you\'re buying your first home, investing in commercial space, or seeking a trusted partner to manage your portfolio, our mission is to turn your vision into a reality. With years of experience, deep market knowledge, and a commitment to service excellence, Amaken is built on the values of trust, transparency, and tenacity. Every client we serve is a relationship we value, and every property we touch is a promise we keep. Our team blends local expertise with global standards to ensure that your journey &mdash; from inquiry to ownership &mdash; is smooth, secure, and rewarding. Discover what it means to work with a real estate agency that sees more than transactions &mdash; we see possibilities.\"</p>', NULL),
(12, 'Luxury & Lifestyle Focus', '<p><strong data-start=\"1304\" data-end=\"1333\">Discover Life with Amaken</strong><br data-start=\"1333\" data-end=\"1336\" />Amaken Real Estate is where luxury meets lifestyle. We specialize in curating a premium selection of high-end residential and commercial properties across Dubai and the UAE, tailored to clients who value elegance, sophistication, and comfort. Our portfolio includes some of the region&rsquo;s most sought-after communities, waterfront residences, and iconic landmarks. We believe that a home is more than just bricks and mortar&mdash;it&rsquo;s a reflection of your aspirations and way of life. At Amaken, we work closely with our clients to understand their needs and deliver unmatched experiences, from private property tours to end-to-end concierge-style service. Whether you\'re relocating, upgrading, or investing, our team ensures your journey is smooth, personalized, and aligned with your vision for refined living.</p>', 'prime-locations-to-buy-luxury-mansions-in-dubai-resize.webp'),
(13, 'Customer-Centric & Reliable', '<p><strong data-start=\"2204\" data-end=\"2240\">Your Trusted Real Estate Partner</strong><br data-start=\"2240\" data-end=\"2243\" />At Amaken Real Estate, our mission is simple: to provide exceptional, people-first real estate services that build lasting relationships. We are proud to serve individuals, families, and businesses who are looking to rent, buy, or invest in the UAE&rsquo;s dynamic property market. Our commitment to transparency, reliability, and client satisfaction sets us apart. We listen carefully to your goals and work diligently to match you with the right opportunities. From budget-friendly apartments to long-term investment properties, we offer tailored guidance that removes the stress and guesswork from real estate decisions. Our after-sales support and commitment to service ensure that we&rsquo;re with you every step of the way&mdash;even after the deal is closed. With Amaken, you&rsquo;re not just getting a real estate agent&mdash;you&rsquo;re gaining a dedicated partner.</p>', '960x0.webp'),
(14, 'Global Appeal & Investment-Focused', '<p><strong data-start=\"3154\" data-end=\"3208\">Amaken Real Estate &ndash; Bridging You to Opportunities</strong><br data-start=\"3208\" data-end=\"3211\" />In today&rsquo;s fast-paced global economy, real estate is not just about property&mdash;it&rsquo;s about positioning, portfolio, and long-term potential. At Amaken Real Estate, we specialize in connecting both international investors and local buyers with high-growth real estate opportunities across the UAE. With a deep understanding of market cycles, ROI-driven investments, and strategic locations, we serve as a trusted advisor to those seeking profitable ventures and portfolio expansion. Our team offers end-to-end solutions, from investment consultancy and legal guidance to property acquisition and management. Whether you\'re investing from abroad, entering the UAE market for the first time, or expanding a regional portfolio, Amaken brings you the insight, data, and local expertise needed to capitalize on the region&rsquo;s booming real estate sector. We don&rsquo;t just help you buy property&mdash;we help you build lasting value.</p>', 'vela-viento-4-3500x1969.jpg');

