(90, 0, 'Buy Studio Apartment in Auresta Tower JVC – Iconic 63-Story Residential Tower', '<h3><strong>Auresta Tower JVC &ndash; 1-Bedroom Apartment for Sale in Dubai&rsquo;s Tallest Residential Tower</strong></h3>\r\n<p><strong>Live Elevated at Auresta Tower &ndash; JVC&rsquo;s Iconic New Address</strong></p>\r\n<p>Discover luxury living in this <strong>fully furnished 1-bedroom apartment</strong> at <strong>Auresta Tower</strong>, a stunning 63-story skyscraper developed by <strong>Tiger Properties</strong> in the vibrant community of <strong>Jumeirah Village Circle (JVC)</strong>. Designed for modern lifestyles, this apartment offers sophistication, comfort, and connectivity in one of Dubai&rsquo;s most promising investment zones.</p>\r\n<hr />\r\n<h3><strong>Unit Highlights &ndash; 1 Bedroom Apartment</strong></h3>\r\n<ul>\r\n<li>\r\n<p>Fully furnished with modern interiors and elegant finishes</p>\r\n</li>\r\n<li>\r\n<p>Spacious living room with balcony access</p>\r\n</li>\r\n<li>\r\n<p>En-suite master bedroom with built-in wardrobes</p>\r\n</li>\r\n<li>\r\n<p>Stylish open kitchen with high-end appliances</p>\r\n</li>\r\n<li>\r\n<p>Marble flooring, smart climate control &amp; acoustic soundproofing</p>\r\n</li>\r\n<li>\r\n<p>Breathtaking views from mid to high floors</p>\r\n</li>\r\n</ul>\r\n<hr />\r\n<h3><strong>Exclusive Features &amp; Amenities</strong></h3>\r\n<ul>\r\n<li>\r\n<p><strong>Infinity swimming pool</strong> + separate <strong>kids&rsquo; pool</strong></p>\r\n</li>\r\n<li>\r\n<p><strong>Fitness center</strong>, yoga &amp; meditation decks</p>\r\n</li>\r\n<li>\r\n<p>Sauna, steam rooms, and resident lounge</p>\r\n</li>\r\n<li>\r\n<p>Jogging tracks, cycling paths, landscaped gardens</p>\r\n</li>\r\n<li>\r\n<p>Sports courts, BBQ zones, and children&rsquo;s play area</p>\r\n</li>\r\n<li>\r\n<p><strong>24/7 security</strong>, surveillance &amp; concierge service</p>\r\n</li>\r\n</ul>\r\n<hr />\r\n<h3><strong>Prime JVC Location</strong></h3>\r\n<ul>\r\n<li>\r\n<p>Minutes to <strong>Dubai Marina</strong>, <strong>Palm Jumeirah</strong>, <strong>Burj Al Arab</strong>, and <strong>Downtown Dubai</strong></p>\r\n</li>\r\n<li>\r\n<p>Quick access to <strong>Sheikh Zayed Road</strong>, <strong>Al Khail Road</strong>, <strong>Emirates Road</strong>, and <strong>Hessa Street</strong></p>\r\n</li>\r\n<li>\r\n<p>Close to top schools, clinics, mosques, parks, cafes, and shopping malls</p>\r\n</li>\r\n</ul>\r\n<hr />\r\n<h3><strong>Why Invest in Auresta Tower?</strong></h3>\r\n<ul>\r\n<li>\r\n<p>High ROI in a growing residential hub</p>\r\n</li>\r\n<li>\r\n<p>Flexible payment plans</p>\r\n</li>\r\n<li>\r\n<p>Handover in <strong>Q4 2028</strong> &ndash; secure your investment early</p>\r\n</li>\r\n<li>\r\n<p>Ideal for <strong>families, professionals, and investors</strong></p>\r\n</li>\r\n</ul>\r\n<hr />\r\n<p>📞 <strong>Contact us today</strong> to learn more about this luxurious 1-bedroom apartment in Auresta Tower and schedule your <strong>exclusive viewing</strong>. Experience the future of high-rise living in Dubai.</p>', 'Apartment', '1 BHK', 'sale', '1', '2', '0-1', '1', '1', 'Not specified', '670', '1000000', 'Jumeirah Village Circle, Dubai', 'Dubai', 'United arab emirate', '<p>Swimming Pool</p>\r\n<p>BBQ Area</p>\r\n<p>Walking Area</p>\r\n<p>Kids Area</p>\r\n<p>Gym</p>\r\n<p>Basketball Court</p>\r\n<p>Tennis Court</p>\r\n<p>Steam Sauna</p>\r\n<p>Indoor Residents&rsquo; Lounge</p>\r\n<p>Yoga &amp; Meditation Decks</p>\r\n<p>Jogging &amp; Cycling Tracks</p>\r\n<p>Retail Outlets On-site</p>\r\n<p>24/7 Security &amp; CCTV Surveillance</p>\r\n<p>Secure Parking (7 Levels)</p>\r\n<p>High-Speed Elevators</p>\r\n<p>Smart Climate Control</p>\r\n<p>Acoustic Comfort Features</p>\r\n<p>5-Year Payment Plan</p>\r\n<p>3-Year Payment Plan (8% Discount)</p>\r\n<p>Cash Payment Plan (30% Discount)</p>\r\n<p>Furnished Apartments</p>\r\n<p>Kitchen Appliances Included</p>\r\n<p>Expected Handover: Q4 2028</p>\r\n<p>Service Charge: AED 12 per sqft</p>\r\n<p>&nbsp;</p>', 'aimage_686120e973cc86.59437809.jpg', 'aimage1_686120e97461a8.69576616.jpg', 'aimage2_686120e974f8a1.96671003.jpg', 'aimage3_686120e9758db0.45396494.jpg', 'aimage4_686120e975ef46.05245123.jpg', '34', 'available', 'fimage_686120e9765801.92154614.jpg', 'fimage1_686120e976cdf1.08355000.jpg', 'fimage2_686120e977ad84.02770815.jpg', '63', '1', '29-Jun-2025', '', '', '', 'Off Plan', '1', '567098', 'Furnished', '1', '1', 'https://drive.google.com/file/d/154Ql0JO1evQvnLoJraWb9qGokBS_zyfX/view?usp=sharing', 'https://drive.google.com/file/d/1xiVyxe3Klm68QzF6ayh1CKD1MllTm6b3/view?usp=sharing', 'https://drive.google.com/drive/folders/118sLBSDDib2kSA4_0Xn7M8Tdhwqg_bWu?usp=sharing', 'https://drive.google.com/drive/folders/11x03KpVe2WlCOrWvKRKmn6woJTOjGQMX?usp=sharing', '1', '0', 'razahasnain0300@gmail.com', ''),
(91, 0, '2 Bedroom Apartment for Sale in Auresta Tower JVC – Luxury Living in Tallest Residential Tower', '<p>Own a spacious 2-bedroom apartment in Auresta Tower, JVC &ndash; a 63-storey luxury tower by Tiger Properties. Fully furnished with modern interiors, high-end amenities, and a prime location near Dubai Marina, Downtown &amp; major highways. Handover Q4 2028. Book your unit today.</p>\r\n<h3><strong>Auresta Tower JVC &ndash; 2-Bedroom Apartment for Sale in Dubai&rsquo;s Iconic 63-Storey Tower</strong></h3>\r\n<p>Experience elevated living in this <strong>luxurious 2-bedroom apartment</strong> at <strong>Auresta Tower</strong>, the tallest residential tower in <strong>Jumeirah Village Circle (JVC)</strong>. Developed by <strong>Tiger Properties</strong>, this modern architectural gem offers premium homes with world-class amenities and unbeatable location connectivity.</p>\r\n<hr />\r\n<h3><strong>Apartment Highlights &ndash; 2 Bedroom Unit</strong></h3>\r\n<ul>\r\n<li>\r\n<p>Fully furnished with elegant contemporary design</p>\r\n</li>\r\n<li>\r\n<p>Expansive living and dining area with natural lighting</p>\r\n</li>\r\n<li>\r\n<p>2 spacious bedrooms with en-suite bathrooms</p>\r\n</li>\r\n<li>\r\n<p>Modern kitchen with high-end appliances &amp; ample storage</p>\r\n</li>\r\n<li>\r\n<p>Balcony with stunning city or community views</p>\r\n</li>\r\n<li>\r\n<p>Smart home technology, marble flooring &amp; acoustic comfort</p>\r\n</li>\r\n</ul>\r\n<hr />\r\n<h3><strong>Exclusive Amenities</strong></h3>\r\n<ul>\r\n<li>\r\n<p>Infinity-edge swimming pool &amp; dedicated kids&rsquo; pool</p>\r\n</li>\r\n<li>\r\n<p>Fully equipped gym, yoga and meditation areas</p>\r\n</li>\r\n<li>\r\n<p>Sauna, steam rooms, and indoor resident lounge</p>\r\n</li>\r\n<li>\r\n<p>Jogging/cycling tracks, garden spaces, kids&rsquo; play area</p>\r\n</li>\r\n<li>\r\n<p>Sports courts, BBQ zones, and outdoor sitting areas</p>\r\n</li>\r\n<li>\r\n<p>7 Levels of parking, 24/7 security, concierge &amp; CCTV surveillance</p>\r\n</li>\r\n</ul>\r\n<hr />\r\n<h3><strong>Perfectly Located in JVC</strong></h3>\r\n<ul>\r\n<li>\r\n<p>Minutes from <strong>Downtown Dubai</strong>, <strong>Dubai Marina</strong>, <strong>Palm Jumeirah</strong>, <strong>Mall of the Emirates</strong></p>\r\n</li>\r\n<li>\r\n<p>Easy access to <strong>Al Khail Road</strong>, <strong>Emirates Road</strong>, <strong>Hessa Street</strong></p>\r\n</li>\r\n<li>\r\n<p>Surrounded by top schools, hospitals, mosques, parks, cafes, and retail outlets</p>\r\n</li>\r\n</ul>\r\n<hr />\r\n<h3><strong>Investment Highlights</strong></h3>\r\n<ul>\r\n<li>\r\n<p>Completion expected in <strong>Q4 2028</strong></p>\r\n</li>\r\n<li>\r\n<p>High ROI potential in one of Dubai&rsquo;s fastest-growing areas</p>\r\n</li>\r\n<li>\r\n<p>Flexible payment plans available</p>\r\n</li>\r\n<li>\r\n<p>Ideal for end-users and investors alike</p>\r\n</li>\r\n</ul>\r\n<hr />\r\n<p>📞 <strong>Contact us today</strong> to reserve your 2-bedroom unit at Auresta Tower. Live the high-rise lifestyle in Dubai&rsquo;s most promising address.</p>', 'Apartment', '2 BHK', 'sale', '2', '2-3', '0-1', '1', '1', 'Not specified', '1100', '1690000', 'Jumeirah Village Circle, Dubai', 'Dubai', 'United arab emirate', '<p>Swimming Pool</p>\r\n<p>BBQ Area</p>\r\n<p>Walking Area</p>\r\n<p>Kids Area</p>\r\n<p>Gym</p>\r\n<p>Basketball Court</p>\r\n<p>Tennis Court</p>\r\n<p>Steam Sauna</p>\r\n<p>Indoor Residents&rsquo; Lounge</p>\r\n<p>Yoga &amp; Meditation Decks</p>\r\n<p>Jogging &amp; Cycling Tracks</p>\r\n<p>Retail Outlets On-site</p>\r\n<p>24/7 Security &amp; CCTV Surveillance</p>\r\n<p>Secure Parking (7 Levels)</p>\r\n<p>High-Speed Elevators</p>\r\n<p>Smart Climate Control</p>\r\n<p>Acoustic Comfort Features</p>\r\n<p>5-Year Payment Plan</p>\r\n<p>3-Year Payment Plan (8% Discount)</p>\r\n<p>Cash Payment Plan (30% Discount)</p>\r\n<p>Furnished Apartments</p>\r\n<p>Kitchen Appliances Included</p>\r\n<p>Expected Handover: Q4 2028</p>\r\n<p>Service Charge: AED 12 per sqft</p>', 'aimage_686122b25016d7.77194161.jpg', 'aimage1_686122b250e630.72351680.jpg', 'aimage2_686122b251b3a6.94640315.jpg', 'aimage3_686122b2540494.84866624.jpg', 'aimage4_686122b25472b2.09038095.jpg', '80', 'available', 'fimage_686122b256b352.40421416.jpg', 'fimage1_686122b2573545.69968982.jpg', 'fimage2_686122b257c460.10932170.jpg', '63', '1', '29-Jun-2025', '', '', '', 'Off Plan', '1', '358341', 'Furnished', '1', '1', 'https://drive.google.com/file/d/154Ql0JO1evQvnLoJraWb9qGokBS_zyfX/view?usp=sharing', 'https://drive.google.com/file/d/1xiVyxe3Klm68QzF6ayh1CKD1MllTm6b3/view?usp=sharing', 'https://drive.google.com/drive/folders/118sLBSDDib2kSA4_0Xn7M8Tdhwqg_bWu?usp=sharing', 'https://drive.google.com/drive/folders/11x03KpVe2WlCOrWvKRKmn6woJTOjGQMX?usp=sharing', '1', '0', 'razahasnain0300@gmail.com', ''),
(92, 0, '3 Bedroom Duplex for Sale in Auresta Tower JVC – Premium Luxury in Tallest Residential Tower', '<p>Buy a fully furnished 3-bedroom duplex in Auresta Tower, JVC &ndash; a 63-storey luxury tower by Tiger Properties. Featuring spacious layouts, smart technology, and world-class amenities near Dubai Marina &amp; Downtown. Handover Q4 2028. Inquire now.</p>\r\n<h3><strong>Auresta Tower JVC &ndash; 3-Bedroom Duplex for Sale in a Landmark 63-Storey Tower</strong></h3>\r\n<p>Live in rare sophistication at <strong>Auresta Tower</strong>, the tallest residential tower in <strong>Jumeirah Village Circle (JVC)</strong>. This <strong>luxurious 3-bedroom duplex</strong> is a signature residence designed for upscale living, combining open-plan elegance, smart home features, and access to world-class amenities in one of Dubai&rsquo;s most central neighborhoods.</p>\r\n<hr />\r\n<h3><strong>Duplex Highlights &ndash; 3 Bedroom Residence</strong></h3>\r\n<ul>\r\n<li>\r\n<p><strong>Fully furnished duplex</strong> with expansive layouts across two floors</p>\r\n</li>\r\n<li>\r\n<p>3 spacious bedrooms with en-suite bathrooms and built-in wardrobes</p>\r\n</li>\r\n<li>\r\n<p>Elegant living &amp; dining space with double-height ceilings</p>\r\n</li>\r\n<li>\r\n<p>Modern open kitchen with high-end appliances</p>\r\n</li>\r\n<li>\r\n<p>Private balcony with panoramic views of Dubai skyline</p>\r\n</li>\r\n<li>\r\n<p>Premium finishes including marble flooring, smart climate control &amp; sound insulation</p>\r\n</li>\r\n</ul>\r\n<hr />\r\n<h3><strong>Luxury Amenities You Deserve</strong></h3>\r\n<ul>\r\n<li>\r\n<p>Infinity swimming pool + kids&rsquo; pool</p>\r\n</li>\r\n<li>\r\n<p>Fully equipped fitness center, yoga &amp; meditation decks</p>\r\n</li>\r\n<li>\r\n<p>Steam room, sauna, and indoor residents&rsquo; lounge</p>\r\n</li>\r\n<li>\r\n<p>Jogging &amp; cycling tracks, landscaped green spaces</p>\r\n</li>\r\n<li>\r\n<p>BBQ areas, kids&rsquo; playground, and sports courts</p>\r\n</li>\r\n<li>\r\n<p>7-level parking garage, 24/7 security &amp; concierge</p>\r\n</li>\r\n</ul>\r\n<hr />\r\n<h3><strong>Centrally Located in JVC &ndash; Dubai&rsquo;s Family Hub</strong></h3>\r\n<ul>\r\n<li>\r\n<p>Minutes to <strong>Dubai Marina</strong>, <strong>Downtown</strong>, <strong>Burj Al Arab</strong>, and <strong>Palm Jumeirah</strong></p>\r\n</li>\r\n<li>\r\n<p>Quick access to <strong>Sheikh Zayed Road</strong>, <strong>Al Khail Road</strong>, <strong>Emirates Road</strong></p>\r\n</li>\r\n<li>\r\n<p>Surrounded by schools, nurseries, clinics, supermarkets, and community parks</p>\r\n</li>\r\n</ul>\r\n<hr />\r\n<h3><strong>Why Choose This Duplex at Auresta Tower?</strong></h3>\r\n<ul>\r\n<li>\r\n<p>Rare duplex design in a high-rise tower</p>\r\n</li>\r\n<li>\r\n<p>High return on investment and capital appreciation</p>\r\n</li>\r\n<li>\r\n<p>Ideal for large families and luxury property buyers</p>\r\n</li>\r\n<li>\r\n<p><strong>Handover in Q4 2028</strong> with attractive payment plans</p>\r\n</li>\r\n</ul>\r\n<hr />\r\n<p>📞 <strong>Contact us now</strong> to explore this exclusive 3-bedroom duplex at Auresta Tower. Luxury, location, and lifestyle &ndash; all in one stunning address.</p>\r\n<p>&nbsp;</p>', 'Apartment', '3 BHK', 'sale', '3', '3-4', '0-1', '1', '1', 'Not specified', '1,900', '3170000', 'Jumeirah Village Circle, Dubai', 'Dubai', 'United arab emirate', '<p>Swimming Pool</p>\r\n<p>BBQ Area</p>\r\n<p>Walking Area</p>\r\n<p>Kids Area</p>\r\n<p>Gym</p>\r\n<p>Basketball Court</p>\r\n<p>Tennis Court</p>\r\n<p>Steam Sauna</p>\r\n<p>Indoor Residents&rsquo; Lounge</p>\r\n<p>Yoga &amp; Meditation Decks</p>\r\n<p>Jogging &amp; Cycling Tracks</p>\r\n<p>Retail Outlets On-site</p>\r\n<p>24/7 Security &amp; CCTV Surveillance</p>\r\n<p>Secure Parking (7 Levels)</p>\r\n<p>High-Speed Elevators</p>\r\n<p>Smart Climate Control</p>\r\n<p>Acoustic Comfort Features</p>\r\n<p>5-Year Payment Plan</p>\r\n<p>3-Year Payment Plan (8% Discount)</p>\r\n<p>Cash Payment Plan (30% Discount)</p>\r\n<p>Furnished Apartments</p>\r\n<p>Kitchen Appliances Included</p>\r\n<p>Expected Handover: Q4 2028</p>\r\n<p>Service Charge: AED 12 per sqft</p>', 'aimage_6861240322a1c3.99071091.jpg', 'aimage1_68612403233444.67769417.jpg', 'aimage2_6861240323c841.45224981.jpg', 'aimage3_68612403248905.17564593.jpg', 'aimage4_6861240324fc48.85653208.jpg', '80', 'available', 'fimage_6861240326e2d6.56282579.jpg', 'fimage1_68612403274cc7.50026128.jpg', 'fimage2_6861240327c643.02782728.jpg', '63', '1', '29-Jun-2025', '', '', '', 'Off Plan', '1', '636460', 'Furnished', '1', '1', 'https://drive.google.com/file/d/154Ql0JO1evQvnLoJraWb9qGokBS_zyfX/view?usp=sharing', 'https://drive.google.com/file/d/1xiVyxe3Klm68QzF6ayh1CKD1MllTm6b3/view?usp=sharing', 'https://drive.google.com/drive/folders/118sLBSDDib2kSA4_0Xn7M8Tdhwqg_bWu?usp=sharing', 'https://drive.google.com/drive/folders/11x03KpVe2WlCOrWvKRKmn6woJTOjGQMX?usp=sharing', '1', '0', 'razahasnain0300@gmail.com', ''),
(93, 0, 'Binghatti Circle JVC | Iconic High-Rise Residences in Dubai', '<p>Introducing <strong>Binghatti Circle</strong>, the tallest luxury residential tower in <strong>Jumeirah Village Circle (JVC), Dubai</strong>, developed by the award-winning <strong>Binghatti</strong>. This iconic high-rise spans over <strong>60 floors</strong>, offering breathtaking <strong>panoramic views of the Dubai skyline</strong> and setting a new benchmark for upscale living.</p>\r\n<p>Choose from elegantly designed <strong>studios, 1, 2, and 3-bedroom apartments</strong>, each featuring <strong>smart home systems</strong>, <strong>fully equipped kitchens</strong>, and high-quality finishes. The project also includes resort-style amenities and a prime location in one of Dubai&rsquo;s fastest-growing communities.</p>\r\n<p><strong>Completion:</strong> Q2 2027<br /><strong>Prices starting from:</strong> AED 674,999<br /><strong>Flexible Payment Plans:</strong></p>\r\n<ul>\r\n<li>\r\n<p>20/50/30 for international buyers</p>\r\n</li>\r\n<li>\r\n<p>10/40/50 with PDC for UAE residents</p>\r\n</li>\r\n</ul>\r\n<p>Ideal for both <strong>end-users and investors</strong>, Binghatti Circle offers a golden opportunity for those seeking a <strong>10-year UAE Golden Visa</strong> through real estate investment.</p>\r\n<p>Don\'t miss out on this future landmark.<br /><strong>Contact us now for availability, brochures, and unit plans.</strong></p>', 'Apartment', 'Open', 'sale', 'Studio, 1,2 & 3BR', '1-4', '0-2', '1', '1', 'Not specified', '384 Starting', '674,999 Starting', 'Jumeirah Village Circle', 'Dubai', 'UAE', '<p>Tallest Residential Tower in JVC &ndash; 60+ floors</p>\r\n<p>Iconic Architectural Design with Fluid Fa&ccedil;ade</p>\r\n<p>Developed by Award-Winning Binghatti</p>\r\n<p>Smart Home Automation System</p>\r\n<p>Fully Equipped Kitchens</p>\r\n<p>High-Quality Finishes</p>\r\n<p>Floor-to-Ceiling Windows with Skyline Views</p>\r\n<p>Spacious Balconies (Selected Units)</p>\r\n<p>Resort-Style Swimming Pool</p>\r\n<p>State-of-the-Art Gymnasium</p>\r\n<p>Sauna &amp; Steam Rooms</p>\r\n<p>Kids&rsquo; Play Area</p>\r\n<p>Landscaped Gardens</p>\r\n<p>Jogging &amp; Walking Tracks</p>\r\n<p>BBQ Area &amp; Outdoor Seating</p>\r\n<p>24/7 Security and CCTV Surveillance</p>\r\n<p>Concierge &amp; Reception Services</p>\r\n<p>High-Speed Elevators</p>\r\n<p>Dedicated Parking Spaces</p>\r\n<p>Visitor Parking</p>\r\n<p>Retail &amp; Dining Options on Podium Levels</p>\r\n<p>Prime Location in JVC with Easy Access to Al Khail Road &amp; Sheikh Mohammed Bin Zayed Road</p>\r\n<p>Close to Schools, Parks, Supermarkets, and Health Clinics</p>', 'aimage_686280d7509392.51231691.webp', 'aimage1_686280d750dd07.46630464.webp', 'aimage2_686280d750f407.34367250.webp', 'aimage3_686280d7510d19.44096046.webp', 'aimage4_686280d75124a3.91508532.webp', '34', 'available', 'fimage_686280d7513d75.49848397.webp', 'fimage1_686280d7514fd1.49573237.webp', 'fimage2_686280d75166c5.19938003.webp', '74 ', '1', '30-Jun-2025', '', '', '', 'Off Plan', '1', '679998', 'Furnished', '1', '1', '', '', '', 'https://drive.google.com/file/d/1S3rICqyY83z3UiqiDo0gpxONsX6mI8ib/view?usp=sharing', '1', '0', 'razahasnain0300@gmail.com', ''),
(94, 0, 'Studio Apartment for Sale at Azizi Sakandar, Al Furjan | Modern Living in Dubai', '<p data-start=\"270\" data-end=\"634\">Welcome to <strong data-start=\"281\" data-end=\"299\">Azizi Sakandar</strong>, the newest residential landmark by Azizi Developments, rising gracefully as a 15-storey luxury building in the vibrant and well-connected community of <strong data-start=\"452\" data-end=\"465\">Al Furjan</strong>. This contemporary development presents a refined collection of exclusive apartments, thoughtfully designed to combine Mediterranean elegance with modern urban comfort.</p>\r\n<p data-start=\"636\" data-end=\"1012\">Imagine a lifestyle rooted in serenity and sophistication&mdash;Azizi Sakandar is more than a home, it&rsquo;s a peaceful sanctuary where landscaped surroundings, leisure amenities, and community living come together in harmony. The architectural design draws inspiration from Mediterranean aesthetics, infused with family-oriented spaces that bring warmth and balance to everyday living.</p>\r\n<p data-start=\"1014\" data-end=\"1031\"><strong data-start=\"1014\" data-end=\"1031\">Key Features:</strong></p>\r\n<ul data-start=\"1032\" data-end=\"1257\">\r\n<li data-start=\"1032\" data-end=\"1086\">\r\n<p data-start=\"1034\" data-end=\"1086\">Eye-catching fa&ccedil;ade with modern Mediterranean design</p>\r\n</li>\r\n<li data-start=\"1087\" data-end=\"1149\">\r\n<p data-start=\"1089\" data-end=\"1149\">Beautifully crafted interiors and lush internal garden areas</p>\r\n</li>\r\n<li data-start=\"1150\" data-end=\"1199\">\r\n<p data-start=\"1152\" data-end=\"1199\">Family-friendly layouts with high-end finishing</p>\r\n</li>\r\n<li data-start=\"1200\" data-end=\"1257\">\r\n<p data-start=\"1202\" data-end=\"1257\">Peaceful ambiance within a secure and vibrant community</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"1259\" data-end=\"1390\"><strong data-start=\"1259\" data-end=\"1284\">Exceptional Location:</strong><br />Situated in the heart of <strong data-start=\"1310\" data-end=\"1323\">Al Furjan</strong>, Azizi Sakandar offers unmatched convenience. It is surrounded by:</p>\r\n<ul data-start=\"1391\" data-end=\"1710\">\r\n<li data-start=\"1391\" data-end=\"1433\">\r\n<p data-start=\"1393\" data-end=\"1433\">Reputable schools and nursery facilities</p>\r\n</li>\r\n<li data-start=\"1434\" data-end=\"1460\">\r\n<p data-start=\"1436\" data-end=\"1460\">Mosques and family parks</p>\r\n</li>\r\n<li data-start=\"1461\" data-end=\"1500\">\r\n<p data-start=\"1463\" data-end=\"1500\">Shopping centers and community retail</p>\r\n</li>\r\n<li data-start=\"1501\" data-end=\"1710\">\r\n<p data-start=\"1503\" data-end=\"1710\">Quick access to <strong data-start=\"1519\" data-end=\"1540\">Sheikh Zayed Road</strong> and <strong data-start=\"1545\" data-end=\"1572\">Al Furjan Metro Station</strong><br data-start=\"1572\" data-end=\"1575\" />This strategic connectivity ensures residents are just minutes away from Dubai Marina, JBR, Downtown Dubai, and key business districts.</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"1712\" data-end=\"1734\"><strong data-start=\"1712\" data-end=\"1734\">Premium Amenities:</strong></p>\r\n<ul data-start=\"1735\" data-end=\"2112\">\r\n<li data-start=\"1735\" data-end=\"1798\">\r\n<p data-start=\"1737\" data-end=\"1798\">Resort-style <strong data-start=\"1750\" data-end=\"1767\">swimming pool</strong> with shaded relaxation decks</p>\r\n</li>\r\n<li data-start=\"1799\" data-end=\"1859\">\r\n<p data-start=\"1801\" data-end=\"1859\"><strong data-start=\"1801\" data-end=\"1822\">Kids&rsquo; splash pads</strong> and play areas for safe family fun</p>\r\n</li>\r\n<li data-start=\"1860\" data-end=\"1907\">\r\n<p data-start=\"1862\" data-end=\"1907\">Modern <strong data-start=\"1869\" data-end=\"1887\">fitness center</strong> and wellness zone</p>\r\n</li>\r\n<li data-start=\"1908\" data-end=\"1973\">\r\n<p data-start=\"1910\" data-end=\"1973\"><strong data-start=\"1910\" data-end=\"1927\">Jogging lanes</strong> integrated within lush communal landscaping</p>\r\n</li>\r\n<li data-start=\"1974\" data-end=\"2074\">\r\n<p data-start=\"1976\" data-end=\"2074\"><strong data-start=\"1976\" data-end=\"1989\">BBQ areas</strong>, <strong data-start=\"1991\" data-end=\"2006\">onsite caf&eacute;</strong>, and <strong data-start=\"2012\" data-end=\"2037\">multi-purpose lounges</strong> for social and business gatherings</p>\r\n</li>\r\n<li data-start=\"2075\" data-end=\"2112\">\r\n<p data-start=\"2077\" data-end=\"2112\">24/7 security and covered parking</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"2114\" data-end=\"2335\">Azizi Sakandar is designed for those who seek a lifestyle of comfort, elegance, and ease. It offers the perfect blend of privacy, community, and connectivity&mdash;making it an ideal choice for families and professionals alike.</p>', 'Apartment', 'Open', 'sale', 'Studio', '1', '0-1', '1', '1', 'Not specified', '340', '550000', ' Jabal Ali First, Al Furjan in Dubai', 'Dubai', 'UAE', '<p data-start=\"164\" data-end=\"192\">Resort-style swimming pool</p>\r\n<p data-start=\"195\" data-end=\"229\">Kids&rsquo; splash pads and play areas</p>\r\n<p data-start=\"232\" data-end=\"265\">Fully equipped modern gymnasium</p>\r\n<p data-start=\"268\" data-end=\"296\">Jogging and walking tracks</p>\r\n<p data-start=\"299\" data-end=\"328\">Landscaped communal gardens</p>\r\n<p data-start=\"331\" data-end=\"364\">Designated BBQ and picnic areas</p>\r\n<p data-start=\"367\" data-end=\"381\">On-site caf&eacute;</p>\r\n<p data-start=\"384\" data-end=\"414\">Multi-purpose indoor lounges</p>\r\n<p data-start=\"417\" data-end=\"459\">Indoor and outdoor children&rsquo;s play zones</p>\r\n<p data-start=\"462\" data-end=\"494\">24/7 security and surveillance</p>\r\n<p data-start=\"497\" data-end=\"526\">Covered parking for residents</p>', 'aimage_686289b7095120.76331239.webp', 'aimage1_686289b70983d7.00408579.webp', 'aimage2_686289b709a8f2.06433918.webp', 'aimage3_686289b709c9c8.98499821.webp', 'aimage4_686289b709e518.35962935.webp', '34', 'available', 'fimage_686289b70a1d03.11910941.webp', 'fimage1_686289b70a3851.96539132.jpg', 'fimage2_686289b70a5ea7.42351761.webp', '15', '1', '30-Jun-2025', '', '', '', 'Off Plan', '0', '771499', 'Furnished', '1', '1', '', '', '', 'https://drive.google.com/file/d/19m1EnHrq3zv3pakIK8uKZttftIYS6PWf/view?usp=sharing', '1', '0', 'razahasnain0300@gmail.com', ''),
(95, 0, 'Luxury 1BR Apartment | Azizi Sakandar | Al Furjan | Great Investment Opportunity', '<p>&nbsp;</p>\r\n<h3><strong>Modern 1 Bedroom Apartment in Azizi Sakandar, Al Furjan &ndash; Prime Location with Premium Amenities</strong></h3>\r\n<p>Experience elevated living in this beautifully designed <strong>1-bedroom apartment</strong> located in <strong>Azizi Sakandar</strong>, a newly launched luxury residential project in the heart of <strong>Al Furjan</strong>, Dubai. Developed by the renowned Azizi Developments, this 15-storey Mediterranean-inspired building offers a harmonious blend of style, comfort, and functionality&mdash;perfect for individuals, couples, or smart investors.</p>\r\n<p>This unit features a spacious layout with high-quality finishes, an open-plan kitchen, generous living space, and a private balcony that brings in natural light and community views. Ideal for those seeking a peaceful yet well-connected lifestyle, the apartment is situated just minutes from <strong>Sheikh Zayed Road</strong> and <strong>Al Furjan Metro Station</strong>, ensuring convenient access to all parts of the city.</p>\r\n<hr />\r\n<h3><strong>Property Features:</strong></h3>\r\n<ul>\r\n<li>\r\n<p>1 Bedroom</p>\r\n</li>\r\n<li>\r\n<p>1 Bathroom</p>\r\n</li>\r\n<li>\r\n<p>Open-plan living and dining area</p>\r\n</li>\r\n<li>\r\n<p>Modern kitchen with fitted cabinetry</p>\r\n</li>\r\n<li>\r\n<p>Built-in wardrobes</p>\r\n</li>\r\n<li>\r\n<p>Private balcony</p>\r\n</li>\r\n<li>\r\n<p>Floor-to-ceiling windows</p>\r\n</li>\r\n<li>\r\n<p>Dedicated covered parking</p>\r\n</li>\r\n</ul>\r\n<hr />\r\n<h3><strong>Community Amenities:</strong></h3>\r\n<ul>\r\n<li>\r\n<p>Resort-style swimming pool</p>\r\n</li>\r\n<li>\r\n<p>Fully equipped gymnasium</p>\r\n</li>\r\n<li>\r\n<p>Jogging and walking tracks</p>\r\n</li>\r\n<li>\r\n<p>Children&rsquo;s splash pad and play zones</p>\r\n</li>\r\n<li>\r\n<p>Landscaped gardens and BBQ areas</p>\r\n</li>\r\n<li>\r\n<p>On-site caf&eacute; and multi-purpose lounge</p>\r\n</li>\r\n<li>\r\n<p>24/7 security and CCTV surveillance</p>\r\n</li>\r\n<li>\r\n<p>Easy access to metro and main roads</p>\r\n</li>\r\n</ul>\r\n<hr />\r\n<p>This <strong>1 BHK apartment in Azizi Sakandar</strong> is an excellent option for end users and investors looking for affordable luxury in a family-friendly, rapidly growing neighborhood. Al Furjan continues to be one of Dubai&rsquo;s most desirable areas thanks to its community vibe, connectivity, and upcoming developments.</p>', 'Apartment', '1 BHK', 'sale', '1', '2', '0-1', '1', '1', 'Not specified', '650', '1046000', ' Jabal Ali First, Al Furjan in Dubai', 'Dubai', 'UAE', '<p data-start=\"164\" data-end=\"192\">Resort-style swimming pool</p>\r\n<p data-start=\"195\" data-end=\"229\">Kids&rsquo; splash pads and play areas</p>\r\n<p data-start=\"232\" data-end=\"265\">Fully equipped modern gymnasium</p>\r\n<p data-start=\"268\" data-end=\"296\">Jogging and walking tracks</p>\r\n<p data-start=\"299\" data-end=\"328\">Landscaped communal gardens</p>\r\n<p data-start=\"331\" data-end=\"364\">Designated BBQ and picnic areas</p>\r\n<p data-start=\"367\" data-end=\"381\">On-site caf&eacute;</p>\r\n<p data-start=\"384\" data-end=\"414\">Multi-purpose indoor lounges</p>\r\n<p data-start=\"417\" data-end=\"459\">Indoor and outdoor children&rsquo;s play zones</p>\r\n<p data-start=\"462\" data-end=\"494\">24/7 security and surveillance</p>\r\n<p data-start=\"497\" data-end=\"526\">Covered parking for residents</p>', 'aimage_68628a9acd7db7.52068601.webp', 'aimage1_68628a9acda6a4.35482167.webp', 'aimage2_68628a9acdc557.24311418.webp', 'aimage3_68628a9acde3d4.47953235.webp', 'aimage4_68628a9acdfaa1.25743353.webp', '34', 'available', 'fimage_68628a9ace1629.47354940.webp', 'fimage1_68628a9ace2e34.95651480.jpg', 'fimage2_68628a9ace4c75.75638352.webp', '15', '1', '30-Jun-2025', '', '', '', 'Off Plan', '0', '634326', 'Furnished', '1', '1', '', '', '', 'https://drive.google.com/file/d/19m1EnHrq3zv3pakIK8uKZttftIYS6PWf/view?usp=sharing', '1', '0', 'razahasnain0300@gmail.com', ''),
(96, 0, 'Spacious 2 Bedroom Apartment for Sale in Azizi Sakandar, Al Furjan – Luxury Living & Amenities', '<h3 data-start=\"164\" data-end=\"263\">Modern 2 Bedroom Apartment in Azizi Sakandar, Al Furjan &ndash; Stylish Living with Premium Amenities</h3>\r\n<p data-start=\"265\" data-end=\"605\">Discover this spacious <strong data-start=\"288\" data-end=\"311\">2-bedroom apartment</strong> in <strong data-start=\"315\" data-end=\"333\">Azizi Sakandar</strong>, a luxury Mediterranean-inspired development by Azizi Developments, located in the vibrant community of <strong data-start=\"438\" data-end=\"451\">Al Furjan</strong>, Dubai. Perfectly designed for families and professionals, this apartment offers comfortable living with high-quality finishes and a bright, open layout.</p>\r\n<p data-start=\"607\" data-end=\"750\">Enjoy seamless access to major roadways like Sheikh Zayed Road and the nearby Al Furjan Metro Station, ensuring easy connectivity across Dubai.</p>\r\n<hr data-start=\"752\" data-end=\"755\" />\r\n<h3 data-start=\"757\" data-end=\"779\">Property Features:</h3>\r\n<ul data-start=\"780\" data-end=\"980\">\r\n<li data-start=\"780\" data-end=\"794\">\r\n<p data-start=\"782\" data-end=\"794\">2 Bedrooms</p>\r\n</li>\r\n<li data-start=\"795\" data-end=\"810\">\r\n<p data-start=\"797\" data-end=\"810\">2 Bathrooms</p>\r\n</li>\r\n<li data-start=\"811\" data-end=\"847\">\r\n<p data-start=\"813\" data-end=\"847\">Open-plan living and dining area</p>\r\n</li>\r\n<li data-start=\"848\" data-end=\"890\">\r\n<p data-start=\"850\" data-end=\"890\">Modern kitchen with built-in cabinetry</p>\r\n</li>\r\n<li data-start=\"891\" data-end=\"913\">\r\n<p data-start=\"893\" data-end=\"913\">Built-in wardrobes</p>\r\n</li>\r\n<li data-start=\"914\" data-end=\"954\">\r\n<p data-start=\"916\" data-end=\"954\">Private balcony with community views</p>\r\n</li>\r\n<li data-start=\"955\" data-end=\"980\">\r\n<p data-start=\"957\" data-end=\"980\">Covered parking space</p>\r\n</li>\r\n</ul>\r\n<hr data-start=\"982\" data-end=\"985\" />\r\n<h3 data-start=\"987\" data-end=\"1011\">Community Amenities:</h3>\r\n<ul data-start=\"1012\" data-end=\"1259\">\r\n<li data-start=\"1012\" data-end=\"1042\">\r\n<p data-start=\"1014\" data-end=\"1042\">Resort-style swimming pool</p>\r\n</li>\r\n<li data-start=\"1043\" data-end=\"1071\">\r\n<p data-start=\"1045\" data-end=\"1071\">Fully equipped gymnasium</p>\r\n</li>\r\n<li data-start=\"1072\" data-end=\"1102\">\r\n<p data-start=\"1074\" data-end=\"1102\">Jogging and walking tracks</p>\r\n</li>\r\n<li data-start=\"1103\" data-end=\"1139\">\r\n<p data-start=\"1105\" data-end=\"1139\">Kids&rsquo; splash pads and play areas</p>\r\n</li>\r\n<li data-start=\"1140\" data-end=\"1176\">\r\n<p data-start=\"1142\" data-end=\"1176\">Landscaped gardens and BBQ zones</p>\r\n</li>\r\n<li data-start=\"1177\" data-end=\"1219\">\r\n<p data-start=\"1179\" data-end=\"1219\">On-site caf&eacute; and multi-purpose lounges</p>\r\n</li>\r\n<li data-start=\"1220\" data-end=\"1259\">\r\n<p data-start=\"1222\" data-end=\"1259\">24/7 security and CCTV surveillance</p>\r\n</li>\r\n</ul>\r\n<hr data-start=\"1261\" data-end=\"1264\" />\r\n<p data-start=\"1266\" data-end=\"1478\">This <strong data-start=\"1271\" data-end=\"1312\">2-bedroom apartment at Azizi Sakandar</strong> offers an ideal balance of comfort, style, and convenience &mdash; perfect for growing families or investors seeking value in one of Dubai&rsquo;s most sought-after communities.</p>', 'Apartment', '2 BHK', 'sale', '2', '3', '0-1', '1', '1', 'Not specified', '1150', ' 1657000', ' Jabal Ali First, Al Furjan in Dubai', 'Dubai', 'UAE', '<p data-start=\"164\" data-end=\"192\">Resort-style swimming pool</p>\r\n<p data-start=\"195\" data-end=\"229\">Kids&rsquo; splash pads and play areas</p>\r\n<p data-start=\"232\" data-end=\"265\">Fully equipped modern gymnasium</p>\r\n<p data-start=\"268\" data-end=\"296\">Jogging and walking tracks</p>\r\n<p data-start=\"299\" data-end=\"328\">Landscaped communal gardens</p>\r\n<p data-start=\"331\" data-end=\"364\">Designated BBQ and picnic areas</p>\r\n<p data-start=\"367\" data-end=\"381\">On-site caf&eacute;</p>\r\n<p data-start=\"384\" data-end=\"414\">Multi-purpose indoor lounges</p>\r\n<p data-start=\"417\" data-end=\"459\">Indoor and outdoor children&rsquo;s play zones</p>\r\n<p data-start=\"462\" data-end=\"494\">24/7 security and surveillance</p>\r\n<p data-start=\"497\" data-end=\"526\">Covered parking for residents</p>', 'aimage_68628b5362f2d3.28387099.webp', 'aimage1_68628b53632128.22594041.webp', 'aimage2_68628b536342c4.97495161.webp', 'aimage3_68628b536360a2.88896366.webp', 'aimage4_68628b536376e5.01785729.webp', '34', 'available', 'fimage_68628b53639030.13940070.webp', 'fimage1_68628b5363abd7.19485478.jpg', 'fimage2_68628b5363ccc3.30689266.webp', '15', '1', '30-Jun-2025', '', '', '', 'Off Plan', '0', '835778', 'Furnished', '1', '1', '', '', '', 'https://drive.google.com/file/d/19m1EnHrq3zv3pakIK8uKZttftIYS6PWf/view?usp=sharing', '1', '0', 'razahasnain0300@gmail.com', ''),
(97, 0, 'Al Dar | 2 Bedroom Apartment for Sale at Verdes by Haven in Dubai | Contemporary Urban Living ', '<p data-start=\"126\" data-end=\"502\">Discover this spacious <strong data-start=\"149\" data-end=\"191\">2 Bedroom Apartment at Verdes by Haven</strong>, nestled in the sought-after <strong data-start=\"221\" data-end=\"241\">Verdes-Mint-G-02</strong> community with <strong data-start=\"257\" data-end=\"278\">serene park views</strong>. This <strong data-start=\"285\" data-end=\"297\">off-plan</strong> residence spans <strong data-start=\"314\" data-end=\"328\">1,646 sqft</strong> of thoughtfully designed living space. Whether for end-use or investment, this apartment offers a unique opportunity to own a <strong data-start=\"455\" data-end=\"501\">brand-new home directly from the developer</strong>.</p>\r\n<p data-start=\"504\" data-end=\"866\">Currently <strong data-start=\"514\" data-end=\"536\">under construction</strong>, with <strong data-start=\"543\" data-end=\"579\">completion scheduled for Q2 2028</strong>, Verdes by Haven delivers a blend of <strong data-start=\"617\" data-end=\"637\">modern lifestyle</strong> and <strong data-start=\"642\" data-end=\"662\">community living</strong>. Designed for comfort and convenience, the development features a wide range of <strong data-start=\"743\" data-end=\"764\">premium amenities</strong> tailored to enhance your everyday life&mdash;whether you\'re relaxing, staying active, or working from home.</p>', 'Apartment', '2 BHK', 'sale', '2', '2', '1', '1', '1', 'Not specified', '1646 ', '2,057,875', 'Dubailand, Dubai', 'Dubai ', 'United Arab Emirate', '<p data-start=\"894\" data-end=\"906\">Beach Club</p>\r\n<p data-start=\"909\" data-end=\"927\">Community Garden</p>\r\n<p data-start=\"930\" data-end=\"940\">Dog Park</p>\r\n<p data-start=\"943\" data-end=\"954\">Gymnasium</p>\r\n<p data-start=\"957\" data-end=\"965\">Mosque</p>\r\n<p data-start=\"968\" data-end=\"983\">Meeting Rooms</p>\r\n<p data-start=\"986\" data-end=\"1002\">Private Cinema</p>\r\n<p data-start=\"1005\" data-end=\"1020\">Swimming Pool</p>\r\n<p data-start=\"1023\" data-end=\"1034\">Yoga Pods</p>\r\n<p data-start=\"1037\" data-end=\"1054\">Co-working Spaces</p>', 'aimage_68653150e7f0b3.01403338.webp', 'aimage1_68653150e8bd56.28119015.png', 'aimage2_68653150e995c2.06369597.png', 'aimage3_68653150ea9d78.05960697.png', 'aimage4_68653150eb6bf9.90273595.webp', '0', 'available', 'fimage_68653150ebb2c6.59393769.png', 'fimage1_68653150ec7d75.31176115.webp', 'fimage2_68653150ecae52.04234543.png', 'Not specified', '1', '02-Jul-2025', '', '', '', 'Off Plan', '1', '293508', 'Furnished', '1', '1', '', '', '', 'https://drive.google.com/file/d/1nQ7u3a5An9joq28p_MK5IrBF9EbclOQy/view?usp=sharing', '1', '0', 'razahasnain0300@gmail.com', ''),
(98, 0, 'Luxury 5 & 6 Bedroom Mansions at The Wilds Moringa by Aldar in Dubai | From AED 39M', '<p data-start=\"160\" data-end=\"617\">Welcome to <strong data-start=\"171\" data-end=\"201\">The Wilds Moringa Mansions</strong>, a limited collection of just <strong data-start=\"232\" data-end=\"274\">38 ultra-luxury 5- and 6-bedroom homes</strong> set in the lush green heart of <strong data-start=\"306\" data-end=\"326\">The Wilds, Dubai</strong>. Designed by the renowned <strong data-start=\"353\" data-end=\"380\">Nabil Gholam Architects</strong>, these mansions are thoughtfully positioned around <strong data-start=\"432\" data-end=\"448\">Central Park</strong>, offering uninterrupted park views, maximum privacy through natural landscaping, and direct access to one of Dubai&rsquo;s most tranquil and beautifully designed open spaces.</p>\r\n<p data-start=\"619\" data-end=\"982\">Ranging from <strong data-start=\"632\" data-end=\"647\">15,182 sqft</strong>, each mansion embodies a harmonious blend of nature and luxury. Expect <strong data-start=\"719\" data-end=\"739\">rooftop terraces</strong>, <strong data-start=\"741\" data-end=\"759\">sunken lounges</strong>, <strong data-start=\"761\" data-end=\"784\">internal courtyards</strong>, <strong data-start=\"786\" data-end=\"812\">private swimming pools</strong> (with optional Jacuzzis), <strong data-start=\"839\" data-end=\"859\">basement parking</strong>, and architectural elements that use <strong data-start=\"897\" data-end=\"918\">natural materials</strong> and <strong data-start=\"923\" data-end=\"946\">earth-tone palettes</strong> to reduce heat and elevate comfort.</p>\r\n<p data-start=\"984\" data-end=\"1446\">Moringa Mansions is not just a home&mdash;it\'s a philosophy of <strong data-start=\"1041\" data-end=\"1071\">well-being and slow living</strong>. The community features <strong data-start=\"1096\" data-end=\"1126\">cycling and walking tracks</strong>, <strong data-start=\"1128\" data-end=\"1147\">organic gardens</strong>, <strong data-start=\"1149\" data-end=\"1171\">birdwatching decks</strong>, and <strong data-start=\"1177\" data-end=\"1199\">wellness pavilions</strong>, all designed to enrich daily life. With access to a <strong data-start=\"1253\" data-end=\"1266\">clubhouse</strong>, <strong data-start=\"1268\" data-end=\"1295\">tennis and padel courts</strong>, and <strong data-start=\"1301\" data-end=\"1319\">curated retail</strong>, residents enjoy a fully integrated lifestyle just <strong data-start=\"1371\" data-end=\"1405\">25 minutes from Downtown Dubai</strong>&mdash;offering <strong data-start=\"1415\" data-end=\"1445\">serenity without seclusion</strong>.</p>\r\n<p data-start=\"1448\" data-end=\"1682\"><strong data-start=\"1448\" data-end=\"1478\">Starting at AED 39,000,000</strong>, with a flexible <strong data-start=\"1496\" data-end=\"1521\">10/55/35 payment plan</strong>, and <strong data-start=\"1527\" data-end=\"1580\">freehold ownership available to all nationalities</strong>, this is a rare opportunity to own a statement property in one of Dubai&rsquo;s most visionary communities.</p>', 'Villa', 'Open', 'sale', '5 to 6', '6+', '3', '2', '1', 'Not specified', 'From 15,182 ', 'from AED 39,000,000', 'Dubailand, Dubai, United Arab Emirates', 'Dubai ', 'United Arab Emirate', '<p data-start=\"1723\" data-end=\"1752\">The Nest Signature Pavilion</p>\r\n<p data-start=\"1755\" data-end=\"1765\">BBQ Area</p>\r\n<p data-start=\"1768\" data-end=\"1786\">Community Garden</p>\r\n<p data-start=\"1789\" data-end=\"1807\">Basketball Court</p>\r\n<p data-start=\"1810\" data-end=\"1836\">Inspired Pools &amp; Streams</p>\r\n<p data-start=\"1839\" data-end=\"1863\">Bee Conservation Zones</p>\r\n<p data-start=\"1866\" data-end=\"1877\">Yoga Deck</p>\r\n<p data-start=\"1880\" data-end=\"1892\">The Spring</p>\r\n<p data-start=\"1895\" data-end=\"1910\">Nature Trails</p>\r\n<p data-start=\"1913\" data-end=\"1933\">Splash Pool (Kids)</p>\r\n<p data-start=\"1936\" data-end=\"1949\">Zen Gardens</p>\r\n<p data-start=\"1952\" data-end=\"1969\">The Observatory</p>', 'aimage_686537ff708902.22706731.jpg', 'aimage1_686537ff7101b3.47556159.jpg', 'aimage2_686537ff714b19.41042070.jpg', 'aimage3_686537ff7193a7.50618385.jpg', 'aimage4_686537ff71d4c7.88389463.jpg', '0', 'available', 'fimage_686537ff7250e0.75895225.webp', 'fimage1_686537ff729f14.17652532.jpg', 'fimage2_686537ff72e494.90319950.jpg', 'Not specified', '1', '02-Jul-2025', '', '', '', 'Off Plan', '0', '226378', 'Furnished', '1', '1', '', '', '', '', '1', '0', 'razahasnain0300@gmail.com', ''),
(99, 0, 'Luxury 3–5 Bedroom Villas at The Wilds by Aldar in Dubai | From AED 5.1M | Freehold for All', '<h3 data-start=\"302\" data-end=\"332\"><strong data-start=\"309\" data-end=\"332\">Project Description</strong></h3>\r\n<p data-start=\"334\" data-end=\"708\"><strong data-start=\"334\" data-end=\"356\">The Wilds by Aldar</strong> is a masterfully crafted villa community that blends modern architecture with the beauty of nature&mdash;offering residents a tranquil, sustainable lifestyle just minutes from the heart of Dubai. Spanning a lush landscape, this off-plan development features <strong data-start=\"609\" data-end=\"648\">903 exclusive 3 to 5-bedroom villas</strong> designed to deliver both elegance and eco-conscious living.</p>\r\n<p data-start=\"710\" data-end=\"753\">Choose from two distinct villa collections:</p>\r\n<ul data-start=\"755\" data-end=\"1152\">\r\n<li data-start=\"755\" data-end=\"935\">\r\n<p data-start=\"757\" data-end=\"935\"><strong data-start=\"757\" data-end=\"774\">Cassia Villas</strong>: 3, 4, and 5-bedroom villas with open-plan layouts, <strong data-start=\"827\" data-end=\"855\">floor-to-ceiling windows</strong>, and <strong data-start=\"861\" data-end=\"880\">private gardens</strong> that connect seamlessly to the surrounding greenery.</p>\r\n</li>\r\n<li data-start=\"936\" data-end=\"1152\">\r\n<p data-start=\"938\" data-end=\"1152\"><strong data-start=\"938\" data-end=\"960\">Ravenna Residences</strong>: Premium 4 and 5-bedroom homes with <strong data-start=\"997\" data-end=\"1007\">majlis</strong>, <strong data-start=\"1009\" data-end=\"1027\">family lounges</strong>, <strong data-start=\"1029\" data-end=\"1061\">maid&rsquo;s and driver&rsquo;s quarters</strong>, and <strong data-start=\"1067\" data-end=\"1101\">expansive outdoor living areas</strong>&mdash;ideal for larger families and elevated lifestyles.</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"1154\" data-end=\"1324\">Each home is finished with a choice of <strong data-start=\"1193\" data-end=\"1228\">light or dark material palettes</strong>, natural tones, and top-quality fittings to match the project&rsquo;s overall nature-inspired design.</p>\r\n<p data-start=\"1326\" data-end=\"1520\">Located within a serene gated community and offering a <strong data-start=\"1381\" data-end=\"1403\">65/35 payment plan</strong>, <strong data-start=\"1405\" data-end=\"1418\">The Wilds</strong> is just the right balance of peaceful seclusion and city accessibility&mdash;making it a true forever home.</p>\r\n<h3 data-start=\"1527\" data-end=\"1552\"><strong data-start=\"1534\" data-end=\"1552\">Key Highlights</strong></h3>\r\n<ul data-start=\"1554\" data-end=\"2000\">\r\n<li data-start=\"1554\" data-end=\"1589\">\r\n<p data-start=\"1556\" data-end=\"1589\"><strong data-start=\"1556\" data-end=\"1570\">Developer:</strong> Aldar Properties</p>\r\n</li>\r\n<li data-start=\"1590\" data-end=\"1618\">\r\n<p data-start=\"1592\" data-end=\"1618\"><strong data-start=\"1592\" data-end=\"1605\">Location:</strong> Dubai, UAE</p>\r\n</li>\r\n<li data-start=\"1619\" data-end=\"1663\">\r\n<p data-start=\"1621\" data-end=\"1663\"><strong data-start=\"1621\" data-end=\"1639\">Property Type:</strong> 3 to 5 Bedroom Villas</p>\r\n</li>\r\n<li data-start=\"1664\" data-end=\"1726\">\r\n<p data-start=\"1666\" data-end=\"1726\"><strong data-start=\"1666\" data-end=\"1689\">Community Clusters:</strong> Cassia Villas &amp; Ravenna Residences</p>\r\n</li>\r\n<li data-start=\"1727\" data-end=\"1770\">\r\n<p data-start=\"1729\" data-end=\"1770\"><strong data-start=\"1729\" data-end=\"1747\">Built-Up Area:</strong> From <strong data-start=\"1753\" data-end=\"1768\">2,972 Sq.Ft</strong></p>\r\n</li>\r\n<li data-start=\"1771\" data-end=\"1812\">\r\n<p data-start=\"1773\" data-end=\"1812\"><strong data-start=\"1773\" data-end=\"1792\">Starting Price:</strong> <strong data-start=\"1793\" data-end=\"1810\">AED 5,100,000</strong></p>\r\n</li>\r\n<li data-start=\"1813\" data-end=\"1866\">\r\n<p data-start=\"1815\" data-end=\"1866\"><strong data-start=\"1815\" data-end=\"1829\">Ownership:</strong> <strong data-start=\"1830\" data-end=\"1864\">Freehold for all nationalities</strong></p>\r\n</li>\r\n<li data-start=\"1867\" data-end=\"1903\">\r\n<p data-start=\"1869\" data-end=\"1903\"><strong data-start=\"1869\" data-end=\"1888\">Project Status:</strong> <strong data-start=\"1889\" data-end=\"1901\">Off-plan</strong></p>\r\n</li>\r\n<li data-start=\"1904\" data-end=\"2000\">\r\n<p data-start=\"1906\" data-end=\"1925\"><strong data-start=\"1906\" data-end=\"1923\">Payment Plan:</strong></p>\r\n<ul data-start=\"1928\" data-end=\"2000\">\r\n<li data-start=\"1928\" data-end=\"1948\">\r\n<p data-start=\"1930\" data-end=\"1948\">10% Down Payment</p>\r\n</li>\r\n<li data-start=\"1951\" data-end=\"1978\">\r\n<p data-start=\"1953\" data-end=\"1978\">55% During Construction</p>\r\n</li>\r\n<li data-start=\"1981\" data-end=\"2000\">\r\n<p data-start=\"1983\" data-end=\"2000\">35% on Handover</p>\r\n</li>\r\n</ul>\r\n</li>\r\n</ul>', 'Villa', 'Open', 'sale', '3 - 5', '3 - 5+', '1+', '1+', '1', 'Not specified', 'From 2,972', 'From 5,100,000', 'Dubailand, Dubai, UAE', 'Dubai', 'United Arab Emirate', '<p data-start=\"2044\" data-end=\"2073\">The Nest Signature Pavilion</p>\r\n<p data-start=\"2076\" data-end=\"2086\">BBQ Area</p>\r\n<p data-start=\"2089\" data-end=\"2107\">Community Garden</p>\r\n<p data-start=\"2110\" data-end=\"2128\">Basketball Court</p>\r\n<p data-start=\"2131\" data-end=\"2157\">Inspired Pools &amp; Streams</p>\r\n<p data-start=\"2160\" data-end=\"2184\">Bee Conservation Zones</p>\r\n<p data-start=\"2187\" data-end=\"2198\">Yoga Deck</p>\r\n<p data-start=\"2201\" data-end=\"2213\">The Spring</p>\r\n<p data-start=\"2216\" data-end=\"2231\">Nature Trails</p>\r\n<p data-start=\"2234\" data-end=\"2254\">Splash Pool (Kids)</p>\r\n<p data-start=\"2257\" data-end=\"2270\">Zen Gardens</p>\r\n<p data-start=\"2273\" data-end=\"2290\">The Observatory</p>', 'aimage_68653dc77dff59.51522247.jpg', 'aimage1_68653dc77e5ef9.12368870.jpg', 'aimage2_68653dc77ee4b1.73819507.jpg', 'aimage3_68653dc77f5dc6.40477084.jpg', 'aimage4_68653dc78002d5.47808815.jpg', '34', 'available', 'fimage_68653dc78056d9.50169816.jpg', 'fimage1_68653dc780b4e7.63438482.jpg', 'fimage2_68653dc780e0a9.12821890.jpg', 'Not specified', '1', '02-Jul-2025', '', '', '', 'Off Plan', '0', '733383', 'Furnished', '1', '1', '', '', '', 'https://drive.google.com/file/d/1RxoZl_ZxPGxOaSLL-U0U0sK1PvNr9FUy/view?usp=sharing', '1', '0', 'razahasnain0300@gmail.com', '');
