(100, 0, 'Athlon Townhouses & Villas in Dubailand, Dubai (Al Dar)– 3 to 6 Bedroom Homes for Sale', '<h3 data-start=\"196\" data-end=\"261\">🏡 <strong data-start=\"203\" data-end=\"259\">3&ndash;6 Bedroom Villas &amp; Townhouses at Athlon, Dubailand</strong></h3>\r\n<p data-start=\"262\" data-end=\"319\"><strong data-start=\"262\" data-end=\"319\">Dubai&rsquo;s First Wellness-Oriented Residential Community</strong></p>\r\n<p data-start=\"321\" data-end=\"643\"><strong data-start=\"321\" data-end=\"337\">Description:</strong><br data-start=\"337\" data-end=\"340\" />Discover a new standard of living at <strong data-start=\"377\" data-end=\"387\">Athlon</strong>, a visionary wellness-inspired community nestled in the heart of <strong data-start=\"453\" data-end=\"466\">Dubailand</strong>. Designed in partnership with health and fitness experts, Athlon is the first of its kind in Dubai&mdash;where every detail encourages movement, mindfulness, and holistic well-being.</p>\r\n<p data-start=\"645\" data-end=\"966\">Offering <strong data-start=\"654\" data-end=\"694\">3 to 6-bedroom villas and townhouses</strong>, Athlon provides spacious, smartly designed homes that blend contemporary architecture with nature. Whether you\'re a growing family or looking for a serene retreat, Athlon delivers comfort, connection, and convenience&mdash;all within one of Dubai&rsquo;s largest green environments.</p>\r\n<p data-start=\"968\" data-end=\"1212\">With generous living spaces, premium finishes, and private outdoor areas, each residence at Athlon offers a refreshing balance between functionality and luxury&mdash;just 25 minutes from Dubai International Airport and 30 minutes from Jumeirah Beach.</p>\r\n<hr data-start=\"1214\" data-end=\"1217\" />\r\n<h3 data-start=\"1219\" data-end=\"1242\">✅ <strong data-start=\"1225\" data-end=\"1242\">Key Features:</strong></h3>\r\n<h4 data-start=\"1244\" data-end=\"1284\">🏠 <strong data-start=\"1252\" data-end=\"1284\">Villas &amp; Townhouses Include:</strong></h4>\r\n<ul data-start=\"1285\" data-end=\"1694\">\r\n<li data-start=\"1285\" data-end=\"1337\">\r\n<p data-start=\"1287\" data-end=\"1337\">3 to 6 spacious bedrooms with en-suite bathrooms</p>\r\n</li>\r\n<li data-start=\"1338\" data-end=\"1394\">\r\n<p data-start=\"1340\" data-end=\"1394\">Open-plan living and dining areas with natural light</p>\r\n</li>\r\n<li data-start=\"1395\" data-end=\"1428\">\r\n<p data-start=\"1397\" data-end=\"1428\">Private garden and patio area</p>\r\n</li>\r\n<li data-start=\"1429\" data-end=\"1475\">\r\n<p data-start=\"1431\" data-end=\"1475\">Modern kitchens with integrated appliances</p>\r\n</li>\r\n<li data-start=\"1476\" data-end=\"1519\">\r\n<p data-start=\"1478\" data-end=\"1519\">Maid&rsquo;s and driver&rsquo;s room (select units)</p>\r\n</li>\r\n<li data-start=\"1520\" data-end=\"1574\">\r\n<p data-start=\"1522\" data-end=\"1574\">Smart home features (AC, lights, security control)</p>\r\n</li>\r\n<li data-start=\"1575\" data-end=\"1617\">\r\n<p data-start=\"1577\" data-end=\"1617\">Built-in wardrobes and walk-in closets</p>\r\n</li>\r\n<li data-start=\"1618\" data-end=\"1654\">\r\n<p data-start=\"1620\" data-end=\"1654\">Covered parking for 2&ndash;3 vehicles</p>\r\n</li>\r\n<li data-start=\"1655\" data-end=\"1694\">\r\n<p data-start=\"1657\" data-end=\"1694\">Optional private pool (select villas)</p>\r\n</li>\r\n</ul>\r\n<hr data-start=\"2252\" data-end=\"2255\" />\r\n<h3 data-start=\"2257\" data-end=\"2299\">💰 <strong data-start=\"2264\" data-end=\"2283\">Starting Price:</strong> AED 2,800,000</h3>\r\n<h3 data-start=\"2300\" data-end=\"2326\">💳 <strong data-start=\"2307\" data-end=\"2324\">Payment Plan:</strong></h3>\r\n<ul data-start=\"2327\" data-end=\"2430\">\r\n<li data-start=\"2327\" data-end=\"2347\">\r\n<p data-start=\"2329\" data-end=\"2347\">10% Down Payment</p>\r\n</li>\r\n<li data-start=\"2348\" data-end=\"2375\">\r\n<p data-start=\"2350\" data-end=\"2375\">50% During Construction</p>\r\n</li>\r\n<li data-start=\"2376\" data-end=\"2430\">\r\n<p data-start=\"2378\" data-end=\"2430\">40% on Handover<br data-start=\"2393\" data-end=\"2396\" /><strong data-start=\"2396\" data-end=\"2430\">Freehold for All Nationalities</strong></p>\r\n</li>\r\n</ul>\r\n<hr data-start=\"2432\" data-end=\"2435\" />\r\n<h3 data-start=\"2437\" data-end=\"2476\">📩 <strong data-start=\"2444\" data-end=\"2474\">Register Your Interest Now</strong></h3>\r\n<ul data-start=\"2477\" data-end=\"2574\">\r\n<li data-start=\"2477\" data-end=\"2518\">\r\n<p data-start=\"2479\" data-end=\"2518\">📞 Call or WhatsApp: <strong data-start=\"2500\" data-end=\"2516\">055 261 5993</strong></p>\r\n</li>\r\n<li data-start=\"2519\" data-end=\"2543\">\r\n<p data-start=\"2521\" data-end=\"2543\">📥 Download Brochure</p>\r\n</li>\r\n<li data-start=\"2544\" data-end=\"2574\">\r\n<p data-start=\"2546\" data-end=\"2574\">🎯 Get a Free Consultation</p>\r\n</li>\r\n</ul>\r\n<hr data-start=\"2576\" data-end=\"2579\" />', 'Villa', 'Open', 'sale', '3 - 6', '3 - 6+', '1+', '1+', '1', 'Not specified', '2,282', 'From 2,800,000', 'Dubai Island', 'Dubai ', 'United Arab Emirate', '<p data-start=\"1748\" data-end=\"1797\"><strong data-start=\"1748\" data-end=\"1767\">Wellness Center</strong> with fitness, therapy &amp; spa</p>\r\n<p data-start=\"1800\" data-end=\"1843\"><strong data-start=\"1800\" data-end=\"1816\">Little Haven</strong> (Nursery + Kindergarten)</p>\r\n<p data-start=\"1846\" data-end=\"1883\"><strong data-start=\"1846\" data-end=\"1858\">BBQ Area</strong> &amp; outdoor picnic spots</p>\r\n<p data-start=\"1886\" data-end=\"1916\"><strong data-start=\"1886\" data-end=\"1914\">Running &amp; Cycling Tracks</strong></p>\r\n<p data-start=\"1919\" data-end=\"1964\"><strong data-start=\"1919\" data-end=\"1939\">Basketball Court</strong> and outdoor play zones</p>\r\n<p data-start=\"1967\" data-end=\"2016\"><strong data-start=\"1967\" data-end=\"1990\">Meditation Pavilion</strong> &amp; <strong data-start=\"1993\" data-end=\"2014\">Reflexology Paths</strong></p>\r\n<p data-start=\"2019\" data-end=\"2059\"><strong data-start=\"2019\" data-end=\"2034\">Padel Haven</strong> (Paddle Tennis Courts)</p>\r\n<p data-start=\"2062\" data-end=\"2090\"><strong data-start=\"2062\" data-end=\"2088\">Children&rsquo;s Splash Pool</strong></p>\r\n<p data-start=\"2093\" data-end=\"2125\"><strong data-start=\"2093\" data-end=\"2108\">Zen Gardens</strong> for relaxation</p>\r\n<p data-start=\"2128\" data-end=\"2172\"><strong data-start=\"2128\" data-end=\"2151\">Retail Therapy Zone</strong> with shops &amp; cafes</p>\r\n<p data-start=\"2175\" data-end=\"2209\"><strong data-start=\"2175\" data-end=\"2186\">Mosques</strong> inside the community</p>\r\n<p data-start=\"2212\" data-end=\"2250\">24/7 Security and community management</p>', 'aimage_68667f5fac0469.71702730.jpg', 'aimage1_68667f5facb8e1.47351302.jpg', 'aimage2_68667f5fad4243.82738743.jpg', 'aimage3_68667f5fada7e6.49194893.jpg', 'aimage4_68667f5faddc61.89193432.jpg', '34', 'available', 'fimage_68667f5fae0562.44490726.jpg', 'fimage1_68667f5fae2e81.17296055.jpg', 'fimage2_68667f5fae5fe2.13016237.jpg', 'Not specified', '1', '03-Jul-2025', '', '', '', 'Off Plan', '1', '761298', 'Furnished', '1', '1', '', '', '', 'https://drive.google.com/file/d/1_bLkkBjgGNwI-vvW1VfRs2pNYFCY-S9V/view?usp=sharing', '1', '0', 'razahasnain0300@gmail.com', ''),
(101, 0, 'Fahid Beach House Apartments & Studios on Fahid Island, Abu Dhabi – Studio to 3 Bedroom Seaside Homes', '<p data-start=\"244\" data-end=\"592\">Fahid Beach House is poised to become one of the most sought-after beachfront residences on <strong data-start=\"355\" data-end=\"371\">Fahid Island</strong>, a prestigious development by Aldar Properties. This landmark project offers an exclusive collection of <strong data-start=\"476\" data-end=\"522\">studios and 1, 2, and 3-bedroom apartments</strong> designed around wellness, privacy, and harmonious living with nature.</p>\r\n<p data-start=\"594\" data-end=\"894\">Set amidst crystal-clear waters and open skies, Fahid Island is globally recognized as the first <strong data-start=\"691\" data-end=\"718\">Fitwel-certified island</strong>&mdash;a testament to its commitment to health, sustainability, and community. Residents benefit from expansive walkable green spaces, shaded boulevards, and dedicated wellness hubs.</p>\r\n<p data-start=\"896\" data-end=\"1228\">Strategically located just off the Abu Dhabi coast, Fahid Island provides convenient access to major destinations including Yas Island, Saadiyat Island, and Zayed International Airport. This tranquil island lifestyle is enriched by energy-efficient infrastructure and a master plan that balances modern comforts with natural beauty.</p>\r\n<p data-start=\"1230\" data-end=\"1490\">Fahid Beach House offers serene sea views, direct beach access, and a lifestyle defined by ease, balance, and refined simplicity&mdash;making it ideal for individuals, couples, and families seeking a peaceful retreat within Abu Dhabi&rsquo;s thriving waterfront community.</p>', 'Apartment', 'Open', 'sale', 'studio, 1,2 &3 BR', '1 - 4', '0 - 1', '1', '1', 'Not specified', 'soon', 'From 1,800,000', ' Fahid Island off the Abu Dhabi coast', 'Abu Dhabi', 'United Arab Emirate', '<p data-start=\"1554\" data-end=\"1612\">Resort-style <strong data-start=\"1567\" data-end=\"1585\">Infinity Pools</strong> with panoramic sea views</p>\r\n<p data-start=\"1615\" data-end=\"1682\">Multiple <strong data-start=\"1624\" data-end=\"1641\">Sports Courts</strong> including basketball and paddle tennis</p>\r\n<p data-start=\"1685\" data-end=\"1764\">Extensive <strong data-start=\"1695\" data-end=\"1723\">Jogging &amp; Cycling Tracks</strong> integrated into the island&rsquo;s greenbelt</p>\r\n<p data-start=\"1767\" data-end=\"1830\">Wellness-focused <strong data-start=\"1784\" data-end=\"1806\">Green Surroundings</strong> and shaded boulevards</p>\r\n<p data-start=\"1833\" data-end=\"1902\">Dedicated <strong data-start=\"1843\" data-end=\"1859\">Beach Access</strong> for residents with private leisure areas</p>\r\n<p data-start=\"1932\" data-end=\"1977\">Secure <strong data-start=\"1939\" data-end=\"1958\">Kids&rsquo; Play Area</strong> and splash zones</p>\r\n<p data-start=\"1980\" data-end=\"2027\">Community <strong data-start=\"1990\" data-end=\"2001\">Mosques</strong> within walking distance</p>\r\n<p data-start=\"2030\" data-end=\"2081\">Family-friendly <strong data-start=\"2046\" data-end=\"2071\">Restaurants and Caf&eacute;s</strong> on-site</p>\r\n<p data-start=\"2084\" data-end=\"2127\">Nearby childcare facilities and nurseries</p>\r\n<p data-start=\"2157\" data-end=\"2203\">Fully equipped <strong data-start=\"2172\" data-end=\"2180\">Gyms</strong> and wellness centers</p>\r\n<p data-start=\"2206\" data-end=\"2266\">On-site <strong data-start=\"2214\" data-end=\"2237\">Health Care Centers</strong> for convenience and safety</p>\r\n<p data-start=\"2269\" data-end=\"2320\">Relaxing <strong data-start=\"2278\" data-end=\"2302\">Meditation Pavilions</strong> and Zen Gardens</p>\r\n<p data-start=\"2323\" data-end=\"2381\">Retail options for daily essentials and leisure shopping</p>', 'aimage_686682a0740fc9.35937883.jpeg', 'aimage1_686682a0746ee2.03520388.jpeg', 'aimage2_686682a074d028.80247370.jpeg', 'aimage3_686682a0751b36.19695261.jpg', 'aimage4_686682a07536e6.08922392.jpg', '34', 'available', 'fimage_686682a0755cd9.66010293.jpg', 'fimage1_686682a07577c6.59186695.jpeg', 'fimage2_686682a075aa67.06704743.jpg', 'Not specified', '1', '03-Jul-2025', '', '', '', 'Off Plan', '1', '396642', 'Furnished', '1', '1', '', '', '', '', '1', '0', 'razahasnain0300@gmail.com', ''),
(102, 0, 'Al Reeman Residential & Commercial Plots in Al Shamkha (Aldar), Abu Dhabi', '<p data-start=\"292\" data-end=\"444\">Own freehold residential or commercial land in Al Shamkha, Abu Dhabi. Al Reeman plots by Aldar start from AED 690K. Open to all nationalities. Call now!</p>\r\n<p data-start=\"503\" data-end=\"590\"><strong data-start=\"503\" data-end=\"590\">Own Freehold Land in Al Shamkha &ndash; Al Reeman Residential &amp; Commercial Plots by Aldar</strong></p>\r\n<p data-start=\"592\" data-end=\"1006\">Discover an exclusive opportunity to invest in freehold land in one of Abu Dhabi&rsquo;s most rapidly developing neighborhoods&mdash;Al Shamkha. Al Reeman by Aldar Properties offers residential and commercial plots that combine connectivity, flexibility, and future-ready infrastructure. Open to buyers of all nationalities, these plots are ideal for building your dream villa or a profitable mixed-use commercial development.</p>\r\n<h3 data-start=\"1008\" data-end=\"1033\">🏡 Residential Plots:</h3>\r\n<p data-start=\"1034\" data-end=\"1461\">Al Reeman Residential provides the rare chance to design and build a custom home in a community that prioritizes lifestyle and privacy. Whether it&rsquo;s a spacious family villa or a modern retreat, these plots allow full design freedom. With nearby schools, retail outlets, healthcare centers, and green spaces, residents will enjoy a well-balanced lifestyle with seamless access to Yas Island, Masdar City, and downtown Abu Dhabi.</p>\r\n<h3 data-start=\"1463\" data-end=\"1487\">🏢 Commercial Plots:</h3>\r\n<p data-start=\"1488\" data-end=\"1885\">Positioned within a high-growth corridor, Al Reeman Commercial is approved for mid-rise developments (G+5 to G+7). These plots are perfect for constructing residential apartment buildings or mixed-use projects with strong rental yields and capital appreciation. With direct highway access and proximity to business, cultural, and residential hubs, the location supports long-term investment value.</p>\r\n<p data-start=\"1887\" data-end=\"2112\">With plot sizes starting from <strong data-start=\"1917\" data-end=\"1948\">5,381 sq.ft for residential</strong> and <strong data-start=\"1953\" data-end=\"1984\">48,437 sq.ft for commercial</strong>, and pricing beginning at just <strong data-start=\"2016\" data-end=\"2031\">AED 690,000</strong>, Al Reeman is a strategic and affordable entry into Abu Dhabi&rsquo;s property market.</p>\r\n<h3 data-start=\"2114\" data-end=\"2140\">💼 Project Highlights:</h3>\r\n<ul data-start=\"2141\" data-end=\"2444\">\r\n<li data-start=\"2141\" data-end=\"2176\">\r\n<p data-start=\"2143\" data-end=\"2176\"><strong data-start=\"2143\" data-end=\"2156\">Developer</strong>: Aldar Properties</p>\r\n</li>\r\n<li data-start=\"2177\" data-end=\"2216\">\r\n<p data-start=\"2179\" data-end=\"2216\"><strong data-start=\"2179\" data-end=\"2191\">Location</strong>: Al Shamkha, Abu Dhabi</p>\r\n</li>\r\n<li data-start=\"2217\" data-end=\"2261\">\r\n<p data-start=\"2219\" data-end=\"2261\"><strong data-start=\"2219\" data-end=\"2233\">Plot Types</strong>: Residential &amp; Commercial</p>\r\n</li>\r\n<li data-start=\"2262\" data-end=\"2311\">\r\n<p data-start=\"2264\" data-end=\"2311\"><strong data-start=\"2264\" data-end=\"2277\">Ownership</strong>: Freehold for All Nationalities</p>\r\n</li>\r\n<li data-start=\"2312\" data-end=\"2387\">\r\n<p data-start=\"2314\" data-end=\"2387\"><strong data-start=\"2314\" data-end=\"2333\">Starting Prices</strong>: Residential AED 690,000 | Commercial AED 4,590,000</p>\r\n</li>\r\n<li data-start=\"2388\" data-end=\"2444\">\r\n<p data-start=\"2390\" data-end=\"2444\"><strong data-start=\"2390\" data-end=\"2406\">Payment Plan</strong>: 10% Down Payment | 90% on Handover</p>\r\n</li>\r\n</ul>', 'Others', 'Open', 'sale', '--', '--', '--', '--', '--', 'Commercial Plots, Residential Plots', ' From: 5,381', 'From 690,000 ', 'Al Shamkha Area', 'Abu Dhabi', 'United Arab Emirate', '<p data-start=\"85\" data-end=\"100\">Sports Courts</p>\r\n<p data-start=\"103\" data-end=\"124\">Health Care Centers</p>\r\n<p data-start=\"127\" data-end=\"154\">Gyms &amp; Fitness Facilities</p>\r\n<p data-start=\"157\" data-end=\"183\">Jogging &amp; Cycling Tracks</p>\r\n<p data-start=\"186\" data-end=\"204\">Kids&rsquo; Play Areas</p>\r\n<p data-start=\"207\" data-end=\"228\">Restaurants &amp; Cafes</p>\r\n<p data-start=\"231\" data-end=\"258\">Retail &amp; Shopping Outlets</p>\r\n<p data-start=\"261\" data-end=\"270\">Mosques</p>\r\n<p data-start=\"273\" data-end=\"288\" data-is-last-node=\"\">Community Parks</p>', 'aimage_68691dedd861a9.80340185.jpg', 'aimage1_68691dedd8c6c4.76576208.jpg', 'aimage2_68691dedd90b64.06802944.jpg', 'aimage3_68691dedd950d1.02595289.jpg', 'aimage4_68691dedd98657.00722520.jpg', '34', 'available', 'fimage_68691dedd9cb92.74160428.jpg', 'fimage1_68691dedd9f2b4.38476788.jpg', 'fimage2_68691dedda1a08.41134049.jpg', '--', '1', '05-Jul-2025', '', '', '', 'Ready to Move', '1', '270845', 'Unfurnished', '1', '1', '', '', '', '', '1', '0', 'razahasnain0300@gmail.com', ''),
(103, 0, 'Saadiyat Reserve Plots – Freehold Residential Land in Saadiyat Island Aldar', '<p>Buy residential plots on Saadiyat Island with prices from AED 1.8M. Build your custom villa in Abu Dhabi&rsquo;s most prestigious freehold beachfront community.</p>\r\n<p data-start=\"512\" data-end=\"587\"><strong data-start=\"512\" data-end=\"587\">Own Freehold Villa Plots in Saadiyat Island &ndash; Saadiyat Reserve by Aldar</strong></p>\r\n<p data-start=\"589\" data-end=\"908\"><strong data-start=\"589\" data-end=\"609\">Saadiyat Reserve</strong> presents a rare opportunity to own freehold residential land in one of the UAE&rsquo;s most sought-after beachfront destinations&mdash;Saadiyat Island, Abu Dhabi. Developed by Aldar Properties, this exclusive villa community is designed for those who desire a lifestyle immersed in nature, culture, and luxury.</p>\r\n<p data-start=\"910\" data-end=\"1271\">Surrounded by lush mangroves, coastal dunes, and serene green spaces, Saadiyat Reserve invites homeowners to craft their dream villas in a setting that promotes individuality and creativity. With a wide range of plot sizes starting from <strong data-start=\"1147\" data-end=\"1162\">5,059 sq.ft</strong>, buyers have the flexibility to design homes that reflect their lifestyle, values, and architectural tastes.</p>\r\n<p data-start=\"1273\" data-end=\"1639\">Positioned just minutes away from the Louvre Abu Dhabi, Zayed National Museum, and the upcoming Guggenheim Abu Dhabi, the development merges cultural richness with modern living. Residents benefit from a well-connected yet peaceful environment featuring pedestrian-friendly pathways, shaded community zones, and access to Saadiyat&rsquo;s pristine beaches and golf course.</p>\r\n<p data-start=\"1641\" data-end=\"1860\">With prices starting from <strong data-start=\"1667\" data-end=\"1686\">AED 1.8 million</strong>, and a convenient <strong data-start=\"1705\" data-end=\"1727\">10/90 payment plan</strong>, Saadiyat Reserve is a premier investment for homeowners and investors seeking exclusivity, luxury, and capital growth in Abu Dhabi.</p>\r\n<hr data-start=\"1862\" data-end=\"1865\" />\r\n<h3 data-start=\"1867\" data-end=\"1894\">🔹 <strong data-start=\"1874\" data-end=\"1894\">Project Details:</strong></h3>\r\n<ul data-start=\"1896\" data-end=\"2199\">\r\n<li data-start=\"1896\" data-end=\"1931\">\r\n<p data-start=\"1898\" data-end=\"1931\"><strong data-start=\"1898\" data-end=\"1911\">Developer</strong>: Aldar Properties</p>\r\n</li>\r\n<li data-start=\"1932\" data-end=\"1976\">\r\n<p data-start=\"1934\" data-end=\"1976\"><strong data-start=\"1934\" data-end=\"1946\">Location</strong>: Saadiyat Island, Abu Dhabi</p>\r\n</li>\r\n<li data-start=\"1977\" data-end=\"2017\">\r\n<p data-start=\"1979\" data-end=\"2017\"><strong data-start=\"1979\" data-end=\"1996\">Property Type</strong>: Residential Plots</p>\r\n</li>\r\n<li data-start=\"2018\" data-end=\"2067\">\r\n<p data-start=\"2020\" data-end=\"2067\"><strong data-start=\"2020\" data-end=\"2033\">Ownership</strong>: Freehold for All Nationalities</p>\r\n</li>\r\n<li data-start=\"2068\" data-end=\"2105\">\r\n<p data-start=\"2070\" data-end=\"2105\"><strong data-start=\"2070\" data-end=\"2088\">Starting Price</strong>: AED 1,800,000</p>\r\n</li>\r\n<li data-start=\"2106\" data-end=\"2142\">\r\n<p data-start=\"2108\" data-end=\"2142\"><strong data-start=\"2108\" data-end=\"2121\">Plot Size</strong>: From 5,059 Sq. Ft</p>\r\n</li>\r\n<li data-start=\"2143\" data-end=\"2199\">\r\n<p data-start=\"2145\" data-end=\"2199\"><strong data-start=\"2145\" data-end=\"2161\">Payment Plan</strong>: 10% Down Payment | 90% on Handover</p>\r\n</li>\r\n</ul>', 'Others', 'Open', 'sale', '--', '--', '--', '--', '--', 'Residential Plots', 'From 5,059', 'From 1,800,000', 'Saadiyat Island', 'Abu Dhabi', 'United Arab Emirate', '<p data-start=\"2243\" data-end=\"2258\">Sports Courts</p>\r\n<p data-start=\"2261\" data-end=\"2277\">Jogging Tracks</p>\r\n<p data-start=\