(119, NULL, 'Premium Residential Apartments in, Istanbul Turkey – Ready to Move', '<h2><strong>Luxury City-Centre Apartments Istanbul</strong></h2>\r\n<p>Experience <strong>modern urban living</strong> in the heart of<strong> Istanbul</strong>, with these <strong>exclusive residential apartments</strong> thoughtfully designed for <strong>comfort, elegance, and strong investment potential</strong>. Ideal for <strong>families, end-users, and investors</strong>, these residences offer <strong>spacious layouts</strong>, <strong>natural surroundings</strong>, and <strong>eligibility for Turkish Citizenship by Investment</strong>—all within a prime city-centre location.</p>\r\n<hr>\r\n<h2><strong>Property Overview</strong></h2>\r\n<ul>\r\n<li>\r\n<p><strong>Property Numbers:</strong> 4 &amp; 12</p>\r\n</li>\r\n<li>\r\n<p><strong>Blocks:</strong> A &amp; B</p>\r\n</li>\r\n<li>\r\n<p><strong>Floor Levels:</strong> Z (Ground) &amp; 1st Floor</p>\r\n</li>\r\n<li>\r\n<p><strong>Apartment Types:</strong> 2+1 &amp; 1+1</p>\r\n</li>\r\n<li>\r\n<p><strong>Gross Areas:</strong></p>\r\n<ul>\r\n<li>\r\n<p>2+1: <strong>96 m²</strong></p>\r\n</li>\r\n<li>\r\n<p>1+1: <strong>84 m²</strong></p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li>\r\n<p><strong>Views:</strong> <strong>Landscape &amp; Forest Views</strong> – serene greenery within the city</p>\r\n</li>\r\n</ul>\r\n<hr>\r\n<h2><strong>Key Features &amp; Highlights</strong></h2>\r\n<h3><strong>Modern &amp; Functional Design</strong></h3>\r\n<ul>\r\n<li>\r\n<p>Smart layouts maximizing <strong>space efficiency</strong> and <strong>natural light</strong></p>\r\n</li>\r\n<li>\r\n<p>High-quality finishes ensuring <strong>comfort and durability</strong></p>\r\n</li>\r\n<li>\r\n<p>Designed for <strong>contemporary city lifestyles</strong></p>\r\n</li>\r\n</ul>\r\n<h3><strong>Prime City-Centre Location</strong></h3>\r\n<ul>\r\n<li>\r\n<p>Located in <strong>Kağıthane</strong>, one of Istanbul’s most strategic districts</p>\r\n</li>\r\n<li>\r\n<p>Easy access to <strong>business hubs, shopping centres, hospitals, and metro links</strong></p>\r\n</li>\r\n<li>\r\n<p>Excellent connectivity to major roads and transport networks</p>\r\n</li>\r\n</ul>\r\n<h3><strong>Peaceful Natural Surroundings</strong></h3>\r\n<ul>\r\n<li>\r\n<p>Enjoy <strong>green landscape and forest views</strong></p>\r\n</li>\r\n<li>\r\n<p>A rare balance of <strong>urban convenience and natural tranquility</strong></p>\r\n</li>\r\n</ul>\r\n<h3><strong>Investment &amp; Citizenship Opportunity</strong></h3>\r\n<ul>\r\n<li>\r\n<p>Fully <strong>eligible for Turkish Citizenship by Investment</strong></p>\r\n</li>\r\n<li>\r\n<p>High rental demand due to central location</p>\r\n</li>\r\n<li>\r\n<p>Strong potential for <strong>capital appreciation</strong></p>\r\n</li>\r\n</ul>\r\n<h3><strong>Ready-to-Move-In</strong></h3>\r\n<ul>\r\n<li>\r\n<p><strong>Immediate possession available</strong></p>\r\n</li>\r\n<li>\r\n<p>Ideal for <strong>personal living or instant rental income</strong></p>\r\n</li>\r\n</ul>\r\n<hr>\r\n<h2><strong>Pricing &amp; Payment Details</strong></h2>\r\n<h3><strong>Apartment Prices</strong></h3>\r\n<ul>\r\n<li>\r\n<p><strong>2+1 Apartment:</strong><br><strong>USD 450,000</strong> </p>\r\n</li>\r\n<li>\r\n<p><strong>1+1 Apartment:</strong><br><strong>USD 270,000</strong> </p>\r\n</li>\r\n</ul>\r\n<h3><strong>Payment Options</strong></h3>\r\n<ul>\r\n<li>\r\n<p><strong>Down Payment:</strong> Flexible options available</p>\r\n</li>\r\n<li>\r\n<p><strong>Installment Plan:</strong> Available upon request</p>\r\n</li>\r\n</ul>\r\n<hr>\r\n<h2><strong>Legal &amp; Cost Details</strong></h2>\r\n<ul>\r\n<li>\r\n<p><strong>Title Deed:</strong> Ready</p>\r\n</li>\r\n<li>\r\n<p><strong>Expertise Report:</strong> Not required</p>\r\n</li>\r\n<li>\r\n<p><strong>VAT (KDV):</strong> 1%</p>\r\n</li>\r\n<li>\r\n<p><strong>Title Deed Fee:</strong> 2%</p>\r\n</li>\r\n</ul>\r\n<hr>\r\n<h2><strong>Why Choose These Apartments?</strong></h2>\r\n<ul>\r\n<li>\r\n<p><strong>Spacious Living Options:</strong> Perfect for families or lifestyle upgrades</p>\r\n</li>\r\n<li>\r\n<p><strong>Central Urban Living:</strong> Close to Istanbul’s commercial and lifestyle hubs</p>\r\n</li>\r\n<li>\r\n<p><strong>Green &amp; Calm Environment:</strong> Forest and landscape views within the city</p>\r\n</li>\r\n<li>\r\n<p><strong>High Investment Value:</strong> Citizenship eligibility with long-term returns</p>\r\n</li>\r\n<li>\r\n<p><strong>Limited Availability:</strong> Rare opportunity in a prime Istanbul location</p>\r\n</li>\r\n</ul>', 'Apartment', 'Open', 'sale', '2+1 & 2+1', '1', 'Available', '1', 'Availabe', '5th & 20th', '96 m² & 84 m²', '270,000 - 450,000', 'Live close to Istanbul’s business hubs, shopping, and entertainment', 'Istanbul', 'Turkey', '<p>24/7 Security</p>\r\n<p>CCTV Surveillance</p>\r\n<p>Reserved Underground </p>\r\n<p>Open Parking</p>\r\n<p>Landscaped Gardens</p>\r\n<p>Walking Paths</p>\r\n<p>Children Play Areas</p>\r\n<p>Fitness Centre / Gym Social</p>\r\n<p>Multipurpose Rooms</p>\r\n<p>High-Speed</p>\r\n<p>Elevators</p>\r\n<p>Power Backup</p>\r\n<p>Easy Access to Public Transport Roads</p>\r\n<p>Landscape Forest Views</p>\r\n<p>Ready-to-Move Apartments</p>\r\n<p>Energy-Efficient Lighting Modern Plumbing</p>', 'Screenshot_2025-12-26_180721_cb49b4fc5cc4.png', 'Screenshot_2025-12-26_180657_1014c20a6ea4.png', 'Screenshot_2025-12-26_180541_1e77949564ad.png', 'Screenshot_2025-12-26_180602_4eb9a1da7831.png', 'WhatsApp_Image_2025-12-26_at_5_12_00_PM_9578e200bf9e.jpg', '0', 'available', 'WhatsApp_Image_2025-12-26_at_5_12_01_PM_434f9b5d7c26.jpg', 'WhatsApp_Image_2025-12-26_at_5_51_47_PM_d7439206dcc2.jpg', 'WhatsApp_Image_2025-12-26_at_5_51_46_PM_4ee60340279b.jpg', '-', '0', '26-Dec-2025', '', '', '', 'Ready to Move', '1', '356906', 'Furnished', '1', '1', '', '', '', 'https://drive.google.com/file/d/12N2u1C5kP2Y3J26YqLaddc34vJ8k50y-/view?usp=sharing', '1', '0', 'razahasnain0300@gmail.com', 'USD');

